import { icon } from '../../core/icon.9cd50060ebba.mjs';
import { t } from '../../core/i18n.8907cc90cebd.mjs';
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=(p,k=[])=>Array.isArray(p)?p:k.find(x=>Array.isArray(p?.[x]))?p[k.find(x=>Array.isArray(p?.[x]))]:[];
const TYPE_META={mission:{icon:'activity',label:'Mission'},project:{icon:'projects',label:'Project'},command:{icon:'command',label:'Command'},tool:{icon:'tool',label:'Tool'},capability:{icon:'control',label:'Capability'},memory:{icon:'evidence',label:'Memory'}};
const TYPE_LABELS={mission:['Mission','Nhiệm vụ'],project:['Project','Dự án'],command:['Command','Lệnh'],tool:['Tool','Công cụ'],capability:['Capability','Năng lực'],memory:['Memory','Bộ nhớ']};
const typeLabel=(type,language='en')=>TYPE_LABELS[type]?.[language==='vi'?1:0]??TYPE_META[type]?.label??type;
function indexItems({missions=[],projects=[],commands=[],tools=[],capabilities=[],memory=[]}={}){return [
 ...missions.map(x=>({type:'mission',id:x.id,title:x.objective??x.title??x.id,detail:x.status??'',route:`/missions?id=${encodeURIComponent(x.id)}`,search:`${x.objective??''} ${x.title??''} ${x.status??''} ${x.projectId??''}`})),
 ...projects.map(x=>({type:'project',id:x.id,title:x.name??x.path??x.id,detail:x.path??x.trust??'',route:`/projects?id=${encodeURIComponent(x.id)}`,search:`${x.name??''} ${x.path??''} ${x.id}`})),
 ...commands.map(x=>({type:'command',id:x.id??x.name,title:x.title??x.label??x.name??x.id,detail:x.description??'',route:'/',insert:`/${x.id??x.name}`,search:`${x.title??''} ${x.description??''} ${x.id??x.name??''}`})),
 ...tools.map(x=>({type:'tool',id:x.id??x.name,title:x.title??x.name??x.id,detail:x.description??x.server??'',route:'/control-plane/extensions',search:`${x.title??''} ${x.name??''} ${x.description??''} ${x.server??''}`})),
 ...capabilities.map(x=>({type:'capability',id:x.path??x.id,title:x.path??x.id,detail:`${x.method??'GET'} · ${x.domain??'backend'}`,route:'/control-plane/capabilities',search:`${x.path??''} ${x.method??''} ${x.domain??''}`})),
 ...memory.map(x=>({type:'memory',id:x.id,title:x.title??x.fact??x.id,detail:x.kind??x.status??'',route:'/control-plane/context-memory',search:`${x.title??''} ${x.fact??''} ${x.content??''}`})),
].filter(x=>x.id&&x.title)}
export function createSearchController({api,language='en',capabilities=[]}={}){let state={status:'loading',language,query:'',filter:'all',items:[],error:null,capabilities};const snapshot=()=>structuredClone(state);return Object.freeze({snapshot,async load(){state.status='loading';const r=await Promise.allSettled([api.get('/api/missions'),api.get('/api/projects'),api.get('/api/commands'),api.get('/api/mcp/tools'),api.get('/api/memory?projectId=&limit=100').catch(()=>[])]);const [missions,projects,commands,tools,memory]=r.map(x=>x.status==='fulfilled'?x.value:null);state={...state,status:'ready',items:indexItems({missions:arr(missions,['missions']),projects:arr(projects,['projects']),commands:arr(commands,['commands']),tools:arr(tools,['tools']),capabilities:state.capabilities,memory:arr(memory,['items','memory'])}),error:r.every(x=>x.status==='rejected')?'Nolane runtime could not be reached.':null};return snapshot()},setQuery(query){state.query=String(query??'');return snapshot()},setFilter(filter){state.filter=filter;return snapshot()}})}
export function renderSearchView(state={}){const lang=state.language??'en';const q=String(state.query??'').trim().toLowerCase();const results=(state.items??[]).filter(x=>(state.filter==='all'||x.type===state.filter)&&(!q||`${x.title} ${x.detail} ${x.search}`.toLowerCase().includes(q))).slice(0,100);const counts=Object.fromEntries(['mission','project','command','tool','capability','memory'].map(type=>[type,(state.items??[]).filter(x=>x.type===type).length]));return `<section class="surface-page search-page"><header class="surface-page__header"><div><p class="eyebrow">${lang==='vi'?'Chỉ mục toàn không gian':'Universal index'}</p><h1>${t('search.title',lang)}</h1><p>${t('search.subtitle',lang)}</p></div></header><div class="global-search-box">${icon('search',{size:20})}<input type="search" data-global-search-input value="${esc(state.query??'')}" placeholder="${esc(t('search.placeholder',lang))}" autofocus><kbd>Esc</kbd></div><div class="search-layout"><aside class="search-filters"><button data-search-filter="all" aria-pressed="${state.filter==='all'}"><span>${icon('search',{size:15})} ${lang==='vi'?'Tất cả':'All'}</span><strong>${state.items?.length??0}</strong></button>${Object.entries(TYPE_META).map(([type,meta])=>`<button data-search-filter="${type}" aria-pressed="${state.filter===type}"><span>${icon(meta.icon,{size:15})} ${esc(typeLabel(type,lang))}</span><strong>${counts[type]}</strong></button>`).join('')}</aside><main class="search-results">${state.status==='loading'?`<div class="page-loading"><span class="spinner"></span>${t('common.loading',lang)}</div>`:state.error?`<div class="page-error">${icon('warning',{size:18})}<span>${esc(state.error)}</span></div>`:!q?`<div class="search-hint"><span>${icon('command',{size:23})}</span><h2>${lang==='vi'?'Tìm mọi thứ từ một nơi':'One search for the entire workspace'}</h2><p>${t('search.empty',lang)}</p><div><kbd>↑</kbd><kbd>↓</kbd><span>${lang==='vi'?'để điều hướng':'to navigate'}</span><kbd>Enter</kbd><span>${lang==='vi'?'để mở':'to open'}</span></div></div>`:results.length?`<div class="search-result-list"><header><span>${results.length} ${lang==='vi'?'kết quả':'results'}</span><small>${lang==='vi'?'Sắp xếp theo độ liên quan':'Sorted by relevance'}</small></header>${results.map((item,index)=>{const meta=TYPE_META[item.type]??TYPE_META.capability;return `<a href="#${esc(item.route)}" data-route="${esc(item.route)}" data-search-result="${index}"${index===0?' aria-current="true"':''}><span class="search-result__icon">${icon(meta.icon,{size:17})}</span><span><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small></span><em>${esc(typeLabel(item.type,lang))}</em>${icon('arrow',{size:14,className:'search-result__arrow'})}</a>`}).join('')}</div>`:`<div class="empty-state page-empty"><span>${icon('search',{size:20})}</span><strong>${lang==='vi'?'Không tìm thấy kết quả':'No results found'}</strong><p>${lang==='vi'?'Thử từ khóa khác hoặc mở rộng bộ lọc.':'Try another query or broaden the filter.'}</p></div>`}</main></div></section>`}
